use yew::prelude::*;

use super::header::{DOCS_URL, RELEASES_URL, REPO_URL};
use super::logo::Logo;
use super::nav_link::NavLink;
use crate::i18n::Lang;
use crate::route::Page;

const ISSUES_URL: &str = "https://github.com/are-you-fruits-studio/aphyn/issues";
const CONTRIBUTING_URL: &str =
    "https://github.com/are-you-fruits-studio/aphyn/blob/dev/CONTRIBUTING.md";
const STUDIO_URL: &str = "https://github.com/are-you-fruits-studio";
const SITE_SOURCE_URL: &str = "https://github.com/are-you-fruits-studio/aphyn.org";
/// Generated by cargo-about in CI; lists the Rust crates in the site.
const LICENSES_URL: &str = "/licenses/third-party.html";

#[derive(Properties, PartialEq)]
pub struct FooterProps {
    pub lang: Lang,
    /// The home page gets the full footer, other pages a single line.
    #[prop_or(false)]
    pub full: bool,
}

#[function_component(Footer)]
pub fn footer(props: &FooterProps) -> Html {
    let lang = props.lang;
    if !props.full {
        return html! {
            <footer class="footer">
                <div class="wrap footer-compact">
                    <Logo size={20} />
                    <span>
                        { "© 2026 are-you-fruits-studio · MIT OR Apache-2.0 · " }
                        <a href={SITE_SOURCE_URL}>{ lang.t("footer.site_source") }</a>
                        { " · " }
                        <a href={LICENSES_URL}>{ lang.t("footer.licenses") }</a>
                    </span>
                </div>
            </footer>
        };
    }
    html! {
        <footer class="footer">
            <div class="wrap footer-grid">
                <div>
                    <Logo size={24} />
                    <p class="footer-about">{ lang.t("footer.about") }</p>
                </div>
                <nav class="footer-nav" aria-labelledby="footer-engine">
                    <h2 id="footer-engine">{ lang.t("footer.engine") }</h2>
                    <a href={DOCS_URL}>{ lang.t("nav.docs") }</a>
                    <NavLink to={Page::Examples.route(lang)}>{ lang.t("nav.examples") }</NavLink>
                    <NavLink to={Page::Roadmap.route(lang)}>{ lang.t("nav.roadmap") }</NavLink>
                    <a href={RELEASES_URL}>{ lang.t("nav.releases") }</a>
                </nav>
                <nav class="footer-nav" aria-labelledby="footer-project">
                    <h2 id="footer-project">{ lang.t("footer.project") }</h2>
                    <a href={REPO_URL}>{ "GitHub" }</a>
                    <a href={ISSUES_URL}>{ lang.t("footer.issues") }</a>
                    <a href={CONTRIBUTING_URL}>{ lang.t("footer.contributing") }</a>
                </nav>
                <nav class="footer-nav" aria-labelledby="footer-studio">
                    <h2 id="footer-studio">{ lang.t("footer.studio") }</h2>
                    <a href={STUDIO_URL}>{ "are-you-fruits-studio" }</a>
                    <a href={SITE_SOURCE_URL}>{ lang.t("footer.site_source") }</a>
                </nav>
            </div>
            <div class="wrap footer-legal">
                <span>{ "© 2026 are-you-fruits-studio" }</span>
                <span>
                    { "MIT OR Apache-2.0 · " }
                    <a href={LICENSES_URL}>{ lang.t("footer.licenses") }</a>
                </span>
            </div>
        </footer>
    }
}
